// const cheerio = require('cheerio');

// Make sure the response status code is 200 (OK)
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Load the HTML content into cheerio
const $ = cheerio.load(pm.response.text());

// Extract the text from the first <li> element within <ul class="seasons">
const firstSeasonItem = $('ul.seasons li').first().text().trim();

// Log the extracted text
console.log(firstSeasonItem.split('Current Season'));

// Set an environment variable with the extracted text (optional)
pm.environment.set("firstSeasonItem", firstSeasonItem);

// Test to ensure the text extraction is working correctly
pm.test("Extracted first season item text", function () {
    pm.expect(firstSeasonItem).to.be.a('string').that.is.not.empty;
});
